from collections import Counter

def most_common_letters(text):
    counts = Counter(c for c in text.lower() if c.isalpha())
    if not counts:
        return []
    maximum = max(counts.values())
    return sorted(c for c, n in counts.items() if n == maximum)

print(most_common_letters("Аа Бб 123!"))
print(most_common_letters("123!"))
